mapper.select:
SELECT classes.id, classes.cost, classes.course_count, classes.student_id, COUNT(CASE WHEN records.sign_time BETWEEN classes.start_time AND classes.end_time THEN 1 END) AS usedCount, classes.course_count - COUNT(CASE WHEN records.sign_time BETWEEN classes.start_time AND classes.end_time THEN 1 END) AS useCount FROM (SELECT te.sign_time, st.student_id FROM business_teacher_sign_records te LEFT JOIN business_student_sign_records st ON te.id = st.teacher_sign_id) records Right JOIN (SELECT si.id, si.student_id, cl.start_time, cl.end_time, cl.course_count, cl.cost FROM business_classes cl LEFT JOIN business_classes_sign si ON cl.id = si.classes_id
si.classes_id = #{classesId}
and si.student_id = #{studentId}
) classes ON classes.student_id = records.student_id GROUP BY records.student_id, classes.course_count, classes.cost, classes.id

